import { createClient } from "@supabase/supabase-js";

// Use production only on the canonical live domains. Vercel previews and local testing use isolated staging.
const isProductionHost=['mento-schoolflow.vercel.app','mento-schoolflow-mento-solutions.vercel.app','mento-schoolflow-git-main-mento-solutions.vercel.app'].includes(window.location.hostname);
const SUPABASE_URL=isProductionHost?'https://rkwcfkkckfitcgvstekr.supabase.co':'https://jzrxzbejnudzkhbjyxai.supabase.co';
const SUPABASE_PUBLISHABLE_KEY=isProductionHost?'sb_publishable_eFBNcaDH6ZtRBo2lIRORug_BDmCDFyC':'sb_publishable_nzT3M1YesKsa451fkW3Q5g_F5TPW19o';
const db=createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY);
const $=id=>document.getElementById(id);
let user=null,profile=null,classes=[],students=[],staff=[],guardians=[],marks={},reportRows=[];
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
$('registerDate').value=today();const monthAgo=new Date();monthAgo.setDate(monthAgo.getDate()-29);$('reportFrom').value=[monthAgo.getFullYear(),String(monthAgo.getMonth()+1).padStart(2,'0'),String(monthAgo.getDate()).padStart(2,'0')].join('-');$('reportTo').value=today();
function msg(text,type=''){const el=$('message');el.textContent=text;el.className='message'+(type?' '+type:'');el.classList.remove('hidden');}
function workspaceLoadFailed(error){show('authView');msg('Your sign-in is still active, but SchoolFlow could not finish loading your workspace. '+(error?.message||String(error))+' You can retry without signing in again.','error');$('retryWorkspaceBtn').classList.remove('hidden')}
$('retryWorkspaceBtn').addEventListener('click',async()=>{const b=$('retryWorkspaceBtn');b.disabled=true;b.textContent='Retrying…';try{if(!user){const {data:{session},error}=await db.auth.getSession();if(error)throw error;if(!session)throw new Error('Your session has expired. Please sign in again.');user=session.user;}await loadProfile();b.classList.add('hidden');b.textContent='Retry loading workspace';}catch(error){workspaceLoadFailed(error)}finally{b.disabled=false}});
function clearMsg(){$('message').classList.add('hidden')}
function busy(form,on){form.querySelectorAll('button').forEach(b=>b.disabled=on)}
function show(view){['authView','setupView','appView'].forEach(id=>$(id).classList.toggle('hidden',id!==view));$('signOutBtn').classList.toggle('hidden',view==='authView')}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setTab(tab){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));['overview','attendance','admissions','intake','fees','results','classes','staff','parents','reports','messages','finance'].forEach(t=>$('tab-'+t).classList.toggle('hidden',t!==tab));if(tab==='overview')renderWorkspaceOverview();if(tab==='messages'){prepareStaffNewChat();loadStaffConversations().catch(e=>staffChatStatus(e.message));}if(tab==='parents'&&['admin','head_teacher'].includes(profile?.role))loadParentLinks().catch(e=>parentLinkMessage(e.message,'error'));if(tab==='reports')loadReports().catch(e=>msg(e.message||'Unable to load reports.','error'));if(tab==='admissions')loadAdmissions().catch(e=>msg(e.message||'Unable to load admissions.','error'));if(tab==='intake')renderIntake();if(tab==='fees'&&profile?.role==='admin')loadFeeRecords().catch(e=>msg(e.message||'Unable to load school fees.','error'));if(tab==='results')loadResults().catch(e=>msg(e.message||'Unable to load results.','error'));if(tab==='finance')loadFinanceSection(activeFinanceTab).catch(e=>financeMsg(e.message||'Unable to load finance data.','error'))}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));document.querySelectorAll('[data-open-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.openTab)));

let staffActiveConversation=null,staffChatChannel=null,staffPendingMessageId=null;
function staffChatStatus(t){$('staffChatStatus').textContent=t||''}
function staffNewStatus(t){$('staffNewChatStatus').textContent=t||''}
async function loadStaffConversations(){
 const {data,error}=await db.from('school_conversations').select('id,subject,conversation_type,updated_at').order('updated_at',{ascending:false});
 if(error)throw error;
 $('staffConversationList').innerHTML=(data||[]).map(x=>'<button type="button" class="secondary" style="display:block;width:100%;margin:6px 0;text-align:left" data-staff-conversation="'+esc(x.id)+'"><strong>'+esc(x.subject)+'</strong><br><small>'+esc(x.conversation_type.replaceAll('_',' '))+'</small></button>').join('')||'<p class="notice">No conversations yet.</p>';
}
async function prepareStaffNewChat(){
 const activeProfile=profile;
 if(!activeProfile){staffNewStatus('Your staff profile is not ready. Please sign in again, then reopen Messages.');return;}
 $('staffGroupActions').classList.toggle('hidden',activeProfile.role!=='admin');
 $('staffChatStudent').innerHTML='<option value="">Choose a student</option>'+students.filter(s=>s.active).map(s=>'<option value="'+esc(s.id)+'">'+esc(s.full_name)+'</option>').join('');
 $('staffChatParent').innerHTML='<option value="">Choose a student first</option>';
}
$('staffChatStudent').addEventListener('change',async()=>{
 const id=$('staffChatStudent').value;$('staffChatParent').innerHTML='<option value="">Loading linked parents…</option>';
 if(!id){$('staffChatParent').innerHTML='<option value="">Choose a student first</option>';return}
 try{const {data,error}=await db.from('student_guardians').select('guardian_user_id,guardian_name,guardian_email').eq('student_id',id).not('guardian_user_id','is',null);if(error)throw error;
 $('staffChatParent').innerHTML=(data||[]).map(g=>'<option value="'+esc(g.guardian_user_id)+'">'+esc(g.guardian_name)+(g.guardian_email?' · '+esc(g.guardian_email):'')+'</option>').join('')||'<option value="">No linked parent account</option>';
 if(!data?.length)staffNewStatus('This student has no linked parent account yet. Ask the school admin to link the parent first.');
 }catch(e){$('staffChatParent').innerHTML='<option value="">Unable to load parents</option>';staffNewStatus(e.message)}
});
$('staffStartParentChat').addEventListener('click',async()=>{
 const b=$('staffStartParentChat');b.disabled=true;
 try{const activeProfile=profile;
 if(!activeProfile)throw new Error('Your staff profile is no longer available. Please sign in again.');
 const studentId=$('staffChatStudent').value,recipient=$('staffChatParent').value,subject=$('staffChatSubject').value.trim();
 if(!studentId||!recipient||!subject)throw new Error('Choose a student, linked parent and subject.');
 const {data,error}=await db.rpc('schoolflow_create_conversation',{p_type:activeProfile.role==='admin'?'parent_admin':'parent_teacher',p_student_id:studentId,p_recipient_user_id:recipient,p_subject:subject});
 if(error)throw error;$('staffChatSubject').value='';staffNewStatus('Conversation created.');await loadStaffConversations();await openStaffConversation(data);
 }catch(e){staffNewStatus(e.message||'Could not start conversation.')}finally{b.disabled=false}
});
$('createSchoolGroups').addEventListener('click',async()=>{
 const b=$('createSchoolGroups');b.disabled=true;
 try{const {data,error}=await db.rpc('schoolflow_create_school_groups');if(error)throw error;staffNewStatus('School groups created/refreshed.');await loadStaffConversations();if(Array.isArray(data)&&data[0])await openStaffConversation(data[0].community_conversation_id||data[0]);}
 catch(e){staffNewStatus(e.message||'Could not create school groups.')}finally{b.disabled=false}
});
async function openStaffConversation(id){
 staffActiveConversation=id;staffPendingMessageId=null;if(staffChatChannel){db.removeChannel(staffChatChannel);staffChatChannel=null}
 const {data,error}=await db.from('school_conversations').select('id,subject,conversation_type').eq('id',id).single();if(error)throw error;
 $('staffChatTitle').textContent=data.subject;
 const participant=await db.from('school_conversation_participants').select('user_id').eq('conversation_id',id).eq('user_id',user.id).maybeSingle();
 const canReply=!!participant.data;
 $('staffChatBody').disabled=!canReply;$('staffSendMessage').disabled=!canReply;
 await renderStaffMessages();
 staffChatChannel=db.channel('staff-chat-'+id).on('postgres_changes',{event:'INSERT',schema:'public',table:'school_messages',filter:'conversation_id=eq.'+id},()=>renderStaffMessages().catch(e=>staffChatStatus(e.message))).subscribe();
}
async function renderStaffMessages(){
 if(!staffActiveConversation)return;
 const {data,error}=await db.from('school_messages').select('id,sender_id,body,created_at').eq('conversation_id',staffActiveConversation).order('created_at',{ascending:true}).limit(300);if(error)throw error;
 $('staffChatMessages').innerHTML=(data||[]).map(x=>'<div style="padding:10px;margin:7px 0;border-radius:10px;background:'+(x.sender_id===user.id?'#efedff':'#f7f7fb')+'"><div>'+esc(x.body).replace(/\n/g,'<br>')+'</div><small>'+esc(new Date(x.created_at).toLocaleString())+'</small></div>').join('')||'<p class="muted">No messages yet.</p>';
 $('staffChatMessages').scrollTop=$('staffChatMessages').scrollHeight;
}
async function sendStaffMessage(){
 const body=$('staffChatBody').value.trim();if(!body||!staffActiveConversation)return;
 $('staffSendMessage').disabled=true;staffChatStatus('Sending…');
 if(!staffPendingMessageId)staffPendingMessageId=crypto.randomUUID();
 try{const {error}=await db.from('school_messages').insert({conversation_id:staffActiveConversation,sender_id:user.id,client_message_id:staffPendingMessageId,body});if(error)throw error;$('staffChatBody').value='';staffPendingMessageId=null;staffChatStatus('Sent');await renderStaffMessages()}
 catch(e){staffChatStatus('Message not sent: '+e.message+'. Your text is still here—retry when ready.')}
 finally{$('staffSendMessage').disabled=false}
}
$('staffConversationList').addEventListener('click',e=>{const b=e.target.closest('[data-staff-conversation]');if(b)openStaffConversation(b.dataset.staffConversation).catch(x=>staffChatStatus(x.message))});
$('staffSendMessage').addEventListener('click',sendStaffMessage);
$('staffChatBody').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendStaffMessage()}});

function renderWorkspaceOverview(){
 const activeStudents=students.filter(s=>s.active!==false&&(s.admission_status||'admitted')==='admitted');
 const pendingAdmissions=students.filter(s=>(s.admission_status||'admitted')==='pending').length;
 const teacherCount=staff.filter(s=>s.role==='teacher').length;
 const isTeacher=profile?.role==='teacher',isAdmin=profile?.role==='admin';
 const assignedClass=classes.find(c=>c.teacher_id===user?.id);
 const classStudents=assignedClass?activeStudents.filter(s=>s.class_id===assignedClass.id):[];
 const metrics=isTeacher?[
  ['Assigned class',assignedClass?.name||'Not assigned',assignedClass?'Your teaching assignment':'Ask an administrator to assign a class'],
  ['Students in class',classStudents.length,'Active students in your assigned class'],
  ['Attendance marked',Object.keys(marks).filter(id=>marks[id]).length,'Marks in the selected class register'],
  ['School classes',classes.length,'Classes visible to your account']
 ]:[
  ['Active students',activeStudents.length,'Approved and active student records'],
  ['Classes',classes.length,'Class groups in this school'],
  ['Teaching staff',teacherCount,'Teacher profiles in this workspace'],
  ...(isAdmin?[['Fees collected',naira(feeRecords.reduce((sum,r)=>sum+Number(r.amount_paid||0),0)),'Payments recorded for '+currentAcademicYear()]]:[['Admissions to review',pendingAdmissions,'Applications awaiting a decision']])
 ];
 $('overviewMetrics').innerHTML=metrics.map(x=>'<article class="overview-metric"><div class="overview-metric-label">'+esc(x[0])+'</div><div class="overview-metric-value">'+esc(x[1])+'</div><div class="overview-metric-note">'+esc(x[2])+'</div></article>').join('');
 const firstName=(profile?.full_name||'').trim().split(/\s+/)[0]||'there';
 $('overviewGreeting').textContent='Welcome, '+firstName;
 $('overviewDescription').textContent=isTeacher?'Your class workspace is ready. Keep attendance and learning records up to date.':'Here is a practical snapshot of your school operations.';
 const actions=isTeacher?[['Take attendance','attendance'],['Open my class','intake'],['Enter results','results'],['Messages','messages']]:isAdmin?[['Add a student','classes'],['Review admissions','admissions'],['Record school fees','fees'],['Take attendance','attendance'],['Invite staff','staff'],['View reports','reports']]:[['Review admissions','admissions'],['Manage classes & students','classes'],['Take attendance','attendance'],['View reports','reports']];
 $('overviewActions').innerHTML=actions.map(x=>'<button type="button" class="overview-action" data-open-tab="'+x[1]+'"><span>'+esc(x[0])+'</span><span aria-hidden="true">›</span></button>').join('');
 $('overviewActions').querySelectorAll('[data-open-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.openTab)));
 const snapshot=isTeacher?[['Your assigned class',assignedClass?.name||'No class assigned'],['Active class roster',classStudents.length+' students'],['Attendance status',classStudents.length?(Object.keys(marks).filter(id=>marks[id]).length+' of '+classStudents.length+' marked'):'No roster available'],['Your role','Teacher']]:[['School staff',staff.length+' profiles'],['Active student records',activeStudents.length],['Pending admissions',pendingAdmissions],...(isAdmin?[['Fee records',feeRecords.length+' entries']]:[])];
 $('overviewSnapshot').innerHTML=snapshot.map(x=>'<div class="overview-snapshot-row"><span>'+esc(x[0])+'</span><strong>'+esc(x[1])+'</strong></div>').join('');
 $('workspaceDate').textContent=new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'});
}

/* Finance workspace — server-side RLS remains the authority for every operation. */
const financePermissions=[
 ['finance.overview.view','View finance overview'],['finance.fees.view','View fees and collections'],['finance.fees.record','Record fee payments'],
 ['finance.income.view','View other income'],['finance.income.record','Record other income'],['finance.expenses.view','View expenses'],
 ['finance.expenses.record','Submit expenses'],['finance.expenses.approve','Approve and pay expenses'],
 ['finance.payroll.view','View payroll'],['finance.payroll.manage','Manage salary records'],
 ['finance.payroll.payments.record','Record salary payments'],['finance.payroll.payments.approve','Approve salary payments'],
 ['finance.reports.view','View finance reports'],['finance.audit.view','View audit trail']
];
let financeOwner=false,financeGrants=[],financeVisible=false,financeCurrency='NGN',financeSymbol='₦',activeFinanceTab='overview',financeReportData=[];
const money=v=>financeSymbol+Number(v||0).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2});
function financeMsg(t,type=''){const el=$('financeNotice');el.textContent=t||'';el.className='message'+(type?' '+type:'');el.classList.toggle('hidden',!t)}
function financeCan(p){return financeOwner||financeGrants.some(g=>g.permission_key===p&&!g.revoked_at)}
function financeShowSubtab(tab){activeFinanceTab=tab;document.querySelectorAll('[data-finance-tab]').forEach(b=>b.classList.toggle('active',b.dataset.financeTab===tab));['overview','fees','income','expenses','payroll','reports','audit'].forEach(t=>$('finance-view-'+t).classList.toggle('hidden',t!==tab));}
document.querySelectorAll('[data-finance-tab]').forEach(b=>b.addEventListener('click',()=>{financeShowSubtab(b.dataset.financeTab);loadFinanceSection(b.dataset.financeTab).catch(e=>financeMsg(e.message,'error'))}));
async function refreshFinanceAccess(){
 financeOwner=false;financeGrants=[];financeVisible=false;
 const owner=await db.from('school_ownership_history').select('id').eq('school_id',profile.school_id).eq('owner_user_id',user.id).eq('is_current',true).maybeSingle();
 if(owner.error&&owner.error.code!=='PGRST116')throw owner.error;
 financeOwner=!!owner.data;
 const grants=await db.from('school_finance_permissions').select('id,user_id,permission_key,revoked_at').eq('school_id',profile.school_id);
 if(grants.error)throw grants.error;financeGrants=grants.data||[];
 financeVisible=financeOwner||financeGrants.some(g=>g.user_id===user.id&&!g.revoked_at);
 const nav=document.querySelector('[data-tab="finance"]');nav.classList.toggle('hidden',!financeVisible);
 $('financeAccessPanel').classList.toggle('hidden',!financeOwner);
 const school=await db.from('schools').select('currency_code,currency_symbol').eq('id',profile.school_id).maybeSingle();
 if(!school.error&&school.data){financeCurrency=school.data.currency_code||'NGN';financeSymbol=school.data.currency_symbol||'₦'}
 $('financeCurrencyBadge').textContent=financeCurrency+' · '+financeSymbol;
}
async function financeQuery(table,columns,permission,orderCol='created_at'){
 if(!financeCan(permission))return [];
 const {data,error}=await db.from(table).select(columns).eq('school_id',profile.school_id).order(orderCol,{ascending:false}).limit(250);
 if(error)throw error;return data||[];
}
async function loadFinanceSection(tab){
 if(!financeVisible)return;
 financeMsg('');
 if(tab==='overview')return loadFinanceOverview();
 if(tab==='fees')return loadFinanceFees();
 if(tab==='income')return loadFinanceIncome();
 if(tab==='expenses')return loadFinanceExpenses();
 if(tab==='payroll')return loadFinancePayroll();
 if(tab==='reports')return loadFinanceReport();
 if(tab==='audit')return loadFinanceAudit();
}
async function loadFinanceOverview(){
 const [fee,income,expense,salary]=await Promise.all([
 financeQuery('school_fee_payments','id,amount,paid_at,status,reference','finance.fees.view','paid_at'),
 financeQuery('school_income_records','id,amount,received_at,description,category,status','finance.income.view','received_at'),
 financeQuery('school_expenses','id,amount,expense_date,description,category,status','finance.expenses.view','expense_date'),
 financeQuery('school_salary_payments','id,amount,paid_at,status','finance.payroll.view','paid_at')
 ]);
 const sum=(a,k='amount')=>a.filter(x=>(x.status||'posted')==='posted').reduce((s,x)=>s+Number(x[k]||0),0);
 $('financeKpis').innerHTML=[['Collections',sum(fee)],['Other income',sum(income)],['Expenses',expense.filter(x=>['approved','paid'].includes(x.status)).reduce((s,x)=>s+Number(x.amount||0),0)],['Payroll paid',sum(salary)]].map(x=>'<div class="report-kpi">'+esc(x[0])+'<strong>'+esc(money(x[1]))+'</strong></div>').join('');
 if(financeCan('finance.fees.view')){const {data,error}=await db.from('school_fee_records').select('amount_due,amount_paid').eq('school_id',profile.school_id);if(error)throw error;const due=(data||[]).reduce((s,x)=>s+Math.max(0,Number(x.amount_due||0)-Number(x.amount_paid||0)),0);$('financeOutstanding').textContent=money(due)+' outstanding across '+(data||[]).length+' fee records'}else $('financeOutstanding').textContent='You do not have permission to view fee balances.';
 const recent=[...fee.map(x=>({date:x.paid_at,label:'Fee payment',amount:x.amount})),...income.filter(x=>x.status==='posted').map(x=>({date:x.received_at,label:x.description||x.category,amount:x.amount})),...expense.filter(x=>x.status!=='void').map(x=>({date:x.expense_date,label:x.description||x.category,amount:-Number(x.amount)}))].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,8);
 $('financeRecent').innerHTML=recent.map(x=>'<div class="item"><div><strong>'+esc(x.label)+'</strong><br><small>'+esc(new Date(x.date).toLocaleDateString('en-GB'))+'</small></div><strong>'+esc(money(x.amount))+'</strong></div>').join('')||'<p class="muted">No finance transactions recorded yet.</p>';
}
async function loadFinanceFees(){
 if(!financeCan('finance.fees.view')){$('financeFeeRows').textContent='You do not have permission to view fee balances.';$('financeFeePayments').textContent='';return}
 const {data:records,error}=await db.from('school_fee_records').select('id,student_id,academic_year,term,amount_due,amount_paid,note').eq('school_id',profile.school_id).order('academic_year',{ascending:false}).limit(500);if(error)throw error;
 const names=new Map(students.map(s=>[s.id,s.full_name]));
 $('financeFeeStudent').innerHTML='<option value="">Choose a student fee record</option>'+records.map(r=>'<option value="'+esc(r.id)+'">'+esc(names.get(r.student_id)||'Student')+' · '+esc(r.academic_year)+' · '+esc(r.term)+' · balance '+esc(money(Number(r.amount_due)-Number(r.amount_paid)))+'</option>').join('');
 $('financeFeeRows').innerHTML=records.length?'<table class="report-table"><thead><tr><th>Student</th><th>Year / term</th><th>Due</th><th>Paid</th><th>Balance</th></tr></thead><tbody>'+records.map(r=>'<tr><td>'+esc(names.get(r.student_id)||'Student')+'</td><td>'+esc(r.academic_year)+' · '+esc(r.term)+'</td><td>'+esc(money(r.amount_due))+'</td><td>'+esc(money(r.amount_paid))+'</td><td>'+esc(money(Number(r.amount_due)-Number(r.amount_paid)))+'</td></tr>').join('')+'</tbody></table>':'<p class="muted">No fee records have been created yet. Add fee obligations in School fees first.</p>';
 const pays=await financeQuery('school_fee_payments','id,fee_record_id,amount,paid_at,payment_method,reference,status','finance.fees.view','paid_at');
 const byId=new Map(records.map(r=>[r.id,r]));$('financeFeePayments').innerHTML=pays.length?'<table class="report-table"><thead><tr><th>Date</th><th>Student</th><th>Amount</th><th>Method</th><th>Status</th></tr></thead><tbody>'+pays.map(p=>'<tr><td>'+esc(new Date(p.paid_at).toLocaleDateString('en-GB'))+'</td><td>'+esc(names.get(byId.get(p.fee_record_id)?.student_id)||'Student')+'</td><td>'+esc(money(p.amount))+'</td><td>'+esc(p.payment_method)+'</td><td>'+esc(p.status)+'</td></tr>').join('')+'</tbody></table>':'<p class="muted">No fee receipts recorded yet.</p>';
 $('financeFeeForm').classList.toggle('hidden',!financeCan('finance.fees.record'));
}
$('financeFeeForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button[type=submit]');b.disabled=true;try{const amount=Number($('financeFeeAmount').value);const {error}=await db.rpc('schoolflow_record_fee_payment',{p_fee_record_id:$('financeFeeStudent').value,p_amount:amount,p_payment_method:$('financeFeeMethod').value,p_reference:$('financeFeeReference').value.trim()||null,p_note:$('financeFeeNote').value.trim()||null});if(error)throw error;e.currentTarget.reset();financeMsg('Fee payment saved. A receipt entry has been added to the ledger.','success');await loadFinanceFees()}catch(err){financeMsg(err.message||'Could not record fee payment.','error')}finally{b.disabled=false}});
$('financeRefreshFees').addEventListener('click',()=>loadFinanceFees().catch(e=>financeMsg(e.message,'error')));
async function loadFinanceIncome(){
 const rows=await financeQuery('school_income_records','id,category,description,amount,received_at,source,reference,note,status','finance.income.view','received_at');
 $('financeIncomeRows').innerHTML=rows.length?'<table class="report-table"><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Amount</th><th>Status</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(new Date(r.received_at).toLocaleDateString('en-GB'))+'</td><td>'+esc(r.description)+'</td><td>'+esc(r.category)+'</td><td>'+esc(money(r.amount))+'</td><td>'+esc(r.status)+'</td></tr>').join('')+'</tbody></table>':'<p class="muted">No other income entries recorded yet.</p>';
 $('financeIncomeForm').classList.toggle('hidden',!financeCan('finance.income.record'));
}
$('financeIncomeDate').value=today();
$('financeIncomeForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button[type=submit]');b.disabled=true;try{const {error}=await db.from('school_income_records').insert({school_id:profile.school_id,category:$('financeIncomeCategory').value,description:$('financeIncomeDescription').value.trim(),amount:Number($('financeIncomeAmount').value),received_at:new Date($('financeIncomeDate').value+'T12:00:00').toISOString(),source:$('financeIncomeSource').value.trim()||null,reference:$('financeIncomeReference').value.trim()||null,note:$('financeIncomeNote').value.trim()||null,recorded_by:user.id});if(error)throw error;e.currentTarget.reset();$('financeIncomeDate').value=today();financeMsg('Income entry saved.','success');await loadFinanceIncome()}catch(err){financeMsg(err.message||'Could not save income.','error')}finally{b.disabled=false}});
async function loadFinanceExpenses(){
 const rows=await financeQuery('school_expenses','id,category,description,amount,expense_date,supplier,status,requested_by','finance.expenses.view','expense_date');
 $('financeExpenseRows').innerHTML=rows.length?'<table class="report-table"><thead><tr><th>Date</th><th>Description</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.expense_date)+'</td><td>'+esc(r.description)+'<br><small>'+esc(r.category)+(r.supplier?' · '+esc(r.supplier):'')+'</small></td><td>'+esc(money(r.amount))+'</td><td>'+esc(r.status)+'</td><td>'+(financeCan('finance.expenses.approve')&&r.status==='submitted'?'<button class="secondary" data-expense-action="approve" data-expense-id="'+esc(r.id)+'">Approve</button> <button class="secondary" data-expense-action="reject" data-expense-id="'+esc(r.id)+'">Reject</button>':'')+(financeCan('finance.expenses.approve')&&r.status==='approved'?'<button data-expense-action="mark_paid" data-expense-id="'+esc(r.id)+'">Mark paid</button>':'')+'</td></tr>').join('')+'</tbody></table>':'<p class="muted">No expense records yet.</p>';
 $('financeExpenseForm').classList.toggle('hidden',!financeCan('finance.expenses.record'));
}
$('financeExpenseDate').value=today();
$('financeExpenseForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button[type=submit]');b.disabled=true;try{const {error}=await db.from('school_expenses').insert({school_id:profile.school_id,category:$('financeExpenseCategory').value,description:$('financeExpenseDescription').value.trim(),amount:Number($('financeExpenseAmount').value),expense_date:$('financeExpenseDate').value,supplier:$('financeExpenseSupplier').value.trim()||null,receipt_path:$('financeExpenseReceipt').value.trim()||null,requested_by:user.id,status:'draft'});if(error)throw error;e.currentTarget.reset();$('financeExpenseDate').value=today();financeMsg('Draft expense saved. Submit it for approval from the expense list.','success');await loadFinanceExpenses()}catch(err){financeMsg(err.message||'Could not save expense.','error')}finally{b.disabled=false}});
$('financeExpenseRows').addEventListener('click',async e=>{const b=e.target.closest('[data-expense-action]');if(!b)return;b.disabled=true;try{let reason=null;if(b.dataset.expenseAction==='reject')reason=prompt('Reason for rejecting this expense:');const {error}=await db.rpc('schoolflow_transition_expense',{p_expense_id:b.dataset.expenseId,p_action:b.dataset.expenseAction,p_reason:reason,p_payment_reference:null});if(error)throw error;financeMsg('Expense status updated.','success');await loadFinanceExpenses()}catch(err){financeMsg(err.message||'Could not update expense.','error')}finally{b.disabled=false}});
async function loadFinancePayroll(){
 const canView=financeCan('finance.payroll.view'),canManage=financeCan('finance.payroll.manage');
 if(!canView){$('financePayrollRows').textContent='You do not have payroll viewing access.';$('financeSalaryForm').classList.add('hidden');return}
 const rows=await financeQuery('school_salary_records','id,staff_user_id,pay_period_start,pay_period_end,gross_amount,deductions,net_amount,currency_code,status,note','finance.payroll.view','pay_period_end');
 const staffMap=new Map(staff.map(s=>[s.id,s.full_name]));
 $('financeSalaryStaff').innerHTML='<option value="">Choose staff</option>'+staff.filter(s=>s.role!=='parent').map(s=>'<option value="'+esc(s.id)+'">'+esc(s.full_name)+'</option>').join('');
 $('financePayrollRows').innerHTML=rows.length?'<table class="report-table"><thead><tr><th>Staff / period</th><th>Gross</th><th>Deductions</th><th>Net</th><th>Status</th><th>Payment</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(staffMap.get(r.staff_user_id)||'Staff')+'<br><small>'+esc(r.pay_period_start)+' – '+esc(r.pay_period_end)+'</small></td><td>'+esc(money(r.gross_amount))+'</td><td>'+esc(money(r.deductions))+'</td><td>'+esc(money(r.net_amount))+'</td><td>'+esc(r.status)+'</td><td>'+(financeCan('finance.payroll.payments.record')?'<button class="secondary" data-salary-pay="'+esc(r.id)+'" data-salary-net="'+esc(r.net_amount)+'">Record payment</button>':'')+'</td></tr>').join('')+'</tbody></table>':'<p class="muted">No salary records created yet.</p>';
 $('financeSalaryForm').classList.toggle('hidden',!canManage);
}
$('financeSalaryForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button[type=submit]');b.disabled=true;try{const {error}=await db.from('school_salary_records').insert({school_id:profile.school_id,staff_user_id:$('financeSalaryStaff').value,pay_period_start:$('financeSalaryStart').value,pay_period_end:$('financeSalaryEnd').value,gross_amount:Number($('financeSalaryGross').value),deductions:Number($('financeSalaryDeductions').value),currency_code:financeCurrency,note:$('financeSalaryNote').value.trim()||null,created_by:user.id});if(error)throw error;e.currentTarget.reset();financeMsg('Salary record created.','success');await loadFinancePayroll()}catch(err){financeMsg(err.message||'Could not create salary record.','error')}finally{b.disabled=false}});
$('financePayrollRows').addEventListener('click',async e=>{const b=e.target.closest('[data-salary-pay]');if(!b)return;const amount=prompt('Amount paid (outstanding balance '+money(b.dataset.salaryNet)+'):');if(amount===null)return;const value=Number(amount);if(!Number.isFinite(value)||value<=0){financeMsg('Enter a valid positive payment amount.','error');return}b.disabled=true;try{const {error}=await db.rpc('schoolflow_record_salary_payment',{p_salary_record_id:b.dataset.salaryPay,p_amount:value,p_payment_method:'bank_transfer',p_reference:null,p_note:null});if(error)throw error;financeMsg('Salary payment recorded.','success');await loadFinancePayroll()}catch(err){financeMsg(err.message||'Could not record salary payment.','error')}finally{b.disabled=false}});
async function loadFinanceReport(){
 const from=$('financeReportFrom').value,to=$('financeReportTo').value;
 const tables=[];
 if(financeCan('finance.fees.view'))tables.push(['Fee collections','school_fee_payments','paid_at','finance.fees.view']);
 if(financeCan('finance.income.view'))tables.push(['Other income','school_income_records','received_at','finance.income.view']);
 if(financeCan('finance.expenses.view'))tables.push(['Expenses','school_expenses','expense_date','finance.expenses.view']);
 if(financeCan('finance.payroll.view'))tables.push(['Payroll payments','school_salary_payments','paid_at','finance.payroll.view']);
 const parts=await Promise.all(tables.map(async ([label,table,dateCol,permission])=>{let q=db.from(table).select('id,amount,'+dateCol+',status').eq('school_id',profile.school_id);if(from)q=q.gte(dateCol,from);if(to)q=q.lte(dateCol,to);const {data,error}=await q.order(dateCol,{ascending:false}).limit(500);if(error)throw error;return (data||[]).map(x=>({type:label,date:x[dateCol],amount:Number(x.amount),status:x.status||'posted'}))}));
 financeReportData=parts.flat().filter(x=>x.status==='posted'||x.status==='paid').sort((a,b)=>String(b.date).localeCompare(String(a.date)));
 const total=financeReportData.reduce((s,x)=>s+(x.type==='Expenses'?-x.amount:x.amount),0);
 $('financeReportSummary').innerHTML='<div class="report-kpis"><div class="report-kpi">Entries<strong>'+financeReportData.length+'</strong></div><div class="report-kpi">Net recorded<strong>'+esc(money(total))+'</strong></div></div>';
 $('financeReportRows').innerHTML=financeReportData.length?'<table class="report-table"><thead><tr><th>Date</th><th>Type</th><th>Amount</th></tr></thead><tbody>'+financeReportData.map(x=>'<tr><td>'+esc(String(x.date).slice(0,10))+'</td><td>'+esc(x.type)+'</td><td>'+esc(money(x.type==='Expenses'?-x.amount:x.amount))+'</td></tr>').join('')+'</tbody></table>':'<p class="muted">No ledger entries match this date range and your permissions.</p>';
}
$('financeRunReport').addEventListener('click',()=>loadFinanceReport().catch(e=>financeMsg(e.message,'error')));
$('financeExportReport').addEventListener('click',()=>{if(!financeReportData.length){financeMsg('Run a report with at least one entry before exporting.','error');return}const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv=['Date,Type,Amount',...financeReportData.map(x=>[String(x.date).slice(0,10),x.type,x.type==='Expenses'?-x.amount:x.amount].map(q).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='schoolflow-finance-report.csv';a.click();URL.revokeObjectURL(url)});
async function loadFinanceAudit(){
 if(financeCan('finance.audit.view')){const {data,error}=await db.from('school_finance_audit_log').select('id,action,entity_type,entity_id,details,reason,created_at,actor_user_id').eq('school_id',profile.school_id).order('created_at',{ascending:false}).limit(200);if(error)throw error;$('financeAuditRows').innerHTML=data?.length?'<table class="report-table"><thead><tr><th>When</th><th>Action</th><th>Record</th><th>Reason</th></tr></thead><tbody>'+data.map(x=>'<tr><td>'+esc(new Date(x.created_at).toLocaleString('en-GB'))+'</td><td>'+esc(x.action)+'</td><td>'+esc(x.entity_type)+'</td><td>'+esc(x.reason||'—')+'</td></tr>').join('')+'</tbody></table>':'<p class="muted">No audit events recorded yet.</p>'}else $('financeAuditRows').textContent='You do not have audit-trail permission.';
 if(!financeOwner)return;
 $('financeGrantStaff').innerHTML='<option value="">Choose administrator</option>'+staff.filter(s=>s.role==='admin'&&s.id!==user.id).map(s=>'<option value="'+esc(s.id)+'">'+esc(s.full_name)+'</option>').join('');
 $('financeGrantPermission').innerHTML=financePermissions.map(p=>'<option value="'+esc(p[0])+'">'+esc(p[1])+'</option>').join('');
 const active=financeGrants.filter(g=>!g.revoked_at);
 $('financeGrantRows').innerHTML=active.length?'<table class="report-table"><thead><tr><th>Administrator</th><th>Permission</th><th></th></tr></thead><tbody>'+active.map(g=>'<tr><td>'+esc(staff.find(s=>s.id===g.user_id)?.full_name||'Administrator')+'</td><td>'+esc(g.permission_key)+'</td><td><button class="secondary" data-revoke-finance="'+esc(g.id)+'">Revoke</button></td></tr>').join('')+'</tbody></table>':'<p class="muted">No additional finance permissions have been granted.</p>';
}
$('financeGrantForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button[type=submit]');b.disabled=true;try{const {error}=await db.from('school_finance_permissions').insert({school_id:profile.school_id,user_id:$('financeGrantStaff').value,permission_key:$('financeGrantPermission').value,granted_by:user.id});if(error)throw error;financeMsg('Finance permission granted.','success');await refreshFinanceAccess();await loadFinanceAudit()}catch(err){financeMsg(err.message||'Could not grant permission.','error')}finally{b.disabled=false}});
$('financeGrantRows').addEventListener('click',async e=>{const b=e.target.closest('[data-revoke-finance]');if(!b)return;const reason=prompt('Reason for revoking this finance permission:');if(reason===null)return;b.disabled=true;try{const {error}=await db.rpc('schoolflow_revoke_finance_permission',{p_permission_id:b.dataset.revokeFinance,p_reason:reason||null});if(error)throw error;financeMsg('Finance permission revoked.','success');await refreshFinanceAccess();await loadFinanceAudit()}catch(err){financeMsg(err.message||'Could not revoke access.','error')}finally{b.disabled=false}});

async function loadProfile(){msg('Credentials accepted. Checking your account role…');const {data,error}=await db.from('profiles').select('id,school_id,full_name,role').eq('id',user.id).maybeSingle();if(error)throw new Error('Profile lookup failed: '+error.message);profile=data;if(!profile){const guardian=await db.from('student_guardians').select('student_id').eq('guardian_user_id',user.id).limit(1);if(guardian.error)throw new Error('Account role lookup failed: '+guardian.error.message);if(guardian.data?.length){await db.auth.signOut();user=null;show('authView');msg('This account is registered as a parent. Please sign in through the Parents Portal.','error');return}show('setupView');$('setupFullName').value=user.user_metadata?.full_name||'';clearMsg();return}if(!['admin','head_teacher','teacher'].includes(profile.role)){await db.auth.signOut();user=null;profile=null;show('authView');msg('This account does not have a staff role. Please use the portal assigned to your account.','error');return}await loadWorkspace();await refreshFinanceAccess()}
async function workspaceStep(label,task){msg('Signed in. '+label+'…');try{return await task()}catch(error){throw new Error(label+' failed: '+(error?.message||String(error)))}}
async function loadWorkspace(){if(!user||!profile){show('authView');throw new Error('Your staff profile could not be loaded. Please sign in again.')}show('appView');$('welcomeTitle').textContent=profile.full_name;const {data:school,error:schoolError}=await workspaceStep('Loading school details',()=>db.from('schools').select('name').eq('id',profile.school_id).maybeSingle());if(schoolError)throw new Error('School details failed: '+schoolError.message);$('welcomeSub').textContent=(school?.name||'School workspace')+' · '+profile.role.replace('_',' ');$('roleBadge').textContent=profile.role.replace('_',' ');document.querySelector('[data-tab="admissions"]').classList.toggle('hidden',!['admin','head_teacher'].includes(profile.role));document.querySelector('[data-tab="intake"]').classList.toggle('hidden',profile.role!=='teacher');document.querySelector('[data-tab="fees"]').classList.toggle('hidden',profile.role!=='admin');document.querySelector('[data-tab="parents"]').classList.toggle('hidden',!['admin','head_teacher'].includes(profile.role));$('classCreateArea').classList.toggle('hidden',!['admin','head_teacher'].includes(profile.role));$('studentForm').classList.toggle('hidden',profile.role!=='admin');$('inviteForm').classList.toggle('hidden',!['admin','head_teacher'].includes(profile.role)); $('inviteRole').querySelector('option[value="admin"]').disabled=profile.role!=='admin';$('inviteRole').querySelector('option[value="parent"]').disabled=profile.role!=='admin';$('inviteParentStudentWrap').classList.add('hidden');$('admissionForm').classList.toggle('hidden',profile.role!=='admin');$('admissionDate').value=today();await workspaceStep('Loading staff',loadStaff);await workspaceStep('Loading classes',loadClasses);await workspaceStep('Loading students',loadStudents);await workspaceStep('Loading attendance',loadRegister);await workspaceStep('Loading admissions',loadAdmissions);renderRegister();renderClasses();renderStaff();renderIntake();if(profile.role==='admin')await workspaceStep('Loading fee records',loadFeeRecords);setTab('overview');msg('You are signed in. Your school workspace is ready.','success')}
async function loadClasses(){const activeProfile=profile;if(!activeProfile?.role)throw new Error('Your staff session is no longer available while classes are loading. Please sign in again.');let {data:existingClasses,error:loadError}=await db.from('classes').select('id,name,teacher_id').order('name');if(loadError)throw loadError;existingClasses=existingClasses||[];if(['admin','head_teacher'].includes(activeProfile.role)){const standardClasses=['Pre-Nursery','Nursery 1','Nursery 2','Nursery 3','Primary 1','Primary 2','Primary 3','Primary 4','Primary 5','Primary 6','JS 1','JS 2','JS 3','SS 1','SS 2','SS 3'];const existingNames=new Set(existingClasses.map(c=>c.name.trim().toLowerCase()));const missingClasses=standardClasses.filter(name=>!existingNames.has(name.toLowerCase()));if(missingClasses.length){const {error:seedError}=await db.from('classes').insert(missingClasses.map(name=>({school_id:activeProfile.school_id,name,teacher_id:null})));if(seedError)throw seedError;const {data:refreshedClasses,error:refreshError}=await db.from('classes').select('id,name,teacher_id').order('name');if(refreshError)throw refreshError;existingClasses=refreshedClasses||[];}}const standardOrder=['Pre-Nursery','Nursery 1','Nursery 2','Nursery 3','Primary 1','Primary 2','Primary 3','Primary 4','Primary 5','Primary 6','JS 1','JS 2','JS 3','SS 1','SS 2','SS 3'];classes=existingClasses.sort((a,b)=>{const ai=standardOrder.findIndex(n=>n.toLowerCase()===a.name.trim().toLowerCase()),bi=standardOrder.findIndex(n=>n.toLowerCase()===b.name.trim().toLowerCase());return (ai<0?999:ai)-(bi<0?999:bi)||a.name.localeCompare(b.name)});const opts='<option value="">Choose a class</option>'+classes.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('');$('registerClass').innerHTML=opts;$('studentClass').innerHTML=opts;$('admissionClass').innerHTML=opts;$('classTeacher').innerHTML='<option value="">Unassigned</option>'+staff.filter(p=>p.role==='teacher').map(p=>'<option value="'+esc(p.id)+'">'+esc(p.full_name)+'</option>').join('');$('reportClass').innerHTML='<option value="">All accessible classes</option>'+classes.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('');if(activeProfile.role==='teacher'){$('registerClass').value=classes.find(c=>c.teacher_id===user.id)?.id||'';$('registerClass').disabled=true}else{$('registerClass').disabled=false}}
async function loadStudents(){const {data,error}=await db.from('students').select('id,full_name,student_code,class_id,active,created_at,admission_date,admission_status').order('full_name');if(error)throw error;students=data||[];$("directoryClass").innerHTML='<option value="">All classes</option>'+classes.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('');renderStudentDirectory()}
async function loadStaff(){const {data,error}=await db.from('profiles').select('id,full_name,role').order('full_name');if(error)throw error;staff=data||[]}
function parentLinkMessage(t,type=''){const el=$('parentLinkMessage');el.textContent=t;el.className='message'+(type?' '+type:'');el.classList.remove('hidden')}
async function loadParentLinks(){if(!['admin','head_teacher'].includes(profile?.role))return;$('parentLinkStudent').innerHTML='<option value="">Choose a student</option>'+students.map(s=>'<option value="'+esc(s.id)+'">'+esc(s.full_name)+' · '+esc(s.student_code||'No ID')+'</option>').join('');const {data,error}=await db.from('student_guardians').select('student_id,guardian_name,guardian_email,guardian_phone,guardian_user_id').order('guardian_name');if(error)throw error;const rows=data||[];$('parentLinksList').innerHTML=rows.map(g=>{const st=students.find(s=>s.id===g.student_id);return '<div class="item"><div style="flex:1;min-width:0"><strong>'+esc(st?.full_name||'Student record')+'</strong><br><small>'+esc(g.guardian_name)+' · '+esc(g.guardian_email||'No email recorded')+' · '+esc(g.guardian_phone||'No phone')+'</small></div><span class="status">'+(g.guardian_user_id?'Account linked':'Not linked')+'</span></div>'}).join('')||'<p class="muted">No guardian records found.</p>'}
$('refreshParentLinks').addEventListener('click',()=>loadParentLinks().catch(e=>parentLinkMessage(e.message,'error')));
$('linkParentAccount').addEventListener('click',async()=>{const b=$('linkParentAccount');b.disabled=true;try{if(!['admin','head_teacher'].includes(profile?.role))throw new Error('Only school leadership can link parent accounts.');const studentId=$('parentLinkStudent').value,email=$('parentLinkEmail').value.trim().toLowerCase();if(!studentId||!email)throw new Error('Choose a student and enter the guardian email.');const {data,error}=await db.rpc('schoolflow_link_parent_account',{p_student_id:studentId,p_parent_email:email});if(error)throw error;parentLinkMessage('Parent account linked successfully. Guardian records linked: '+data+'.','success');await loadParentLinks()}catch(e){parentLinkMessage(e.message||'Unable to link parent account.','error')}finally{b.disabled=false}});
function renderAdmissions(){const q=$('admissionSearch').value.trim().toLowerCase(),filter=$('admissionStatusFilter').value;const rows=students.filter(s=>{const g=guardians.find(x=>x.student_id===s.id);return (!q||s.full_name.toLowerCase().includes(q)||(s.student_code||'').toLowerCase().includes(q)||(g?.guardian_name||'').toLowerCase().includes(q)||(g?.guardian_phone||'').toLowerCase().includes(q))&&(filter==='all'||(s.admission_status||'admitted')===filter)});const pending=students.filter(s=>(s.admission_status||'admitted')==='pending').length;$('admissionCount').textContent=pending+' pending';const canReview=['admin','head_teacher'].includes(profile.role);$('admissionsList').innerHTML=rows.map(s=>{const cl=classes.find(c=>c.id===s.class_id);const status=s.admission_status||'admitted';const g=guardians.find(x=>x.student_id===s.id);return '<div class="item"><div style="flex:1;min-width:0"><strong>'+esc(s.full_name)+'</strong><br><small>'+esc(s.student_code||'Admission number pending')+' · '+esc(cl?.name||'Class unavailable')+'</small><br><small>Admission date: '+esc(s.admission_date||'Not set')+' · Guardian: '+esc(g?.guardian_name||'Not provided')+' · '+esc(g?.guardian_phone||'No phone')+(g?.guardian_email?' · '+esc(g.guardian_email):'')+'</small>'+(g?.date_of_birth?'<br><small>Date of birth: '+esc(g.date_of_birth)+'</small>':'')+'<br><span class="status">'+esc(status)+'</span></div>'+(canReview&&status==='pending'?'<div class="row"><button type="button" data-admission-action="approve" data-student-id="'+esc(s.id)+'">Approve</button><button type="button" class="danger" data-admission-action="reject" data-student-id="'+esc(s.id)+'">Reject</button></div>':'')+'</div>'}).join('')||'<p class="muted">No applications match this filter.</p>'}
async function loadAdmissions(){if(!profile)return;const canReview=['admin','head_teacher'].includes(profile.role);$('admissionForm').classList.toggle('hidden',profile.role!=='admin');$('admissionClass').innerHTML='<option value="">Choose a class</option>'+classes.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('');guardians=[];if(canReview){const {data,error}=await db.from('student_guardians').select('student_id,date_of_birth,guardian_name,guardian_phone,guardian_email');if(error)throw error;guardians=data||[]}renderAdmissions()}
function currentAcademicYear(){const d=new Date(),start=d.getMonth()>=8?d.getFullYear():d.getFullYear()-1;return start+'/'+(start+1)}
function naira(value){return new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:2}).format(Number(value)||0)}
let feeRecords=[];
async function loadFeeRecords(){if(profile?.role!=='admin')return;const year=$('feeFilterYear').value.trim()||currentAcademicYear();if(!$('feeAcademicYear').value)$('feeAcademicYear').value=year;if(!$('feeFilterYear').value)$('feeFilterYear').value=year;$('feeStudent').innerHTML='<option value="">Choose a student</option>'+students.filter(s=>s.active&&(s.admission_status||'admitted')==='admitted').map(s=>'<option value="'+esc(s.id)+'">'+esc(s.full_name)+' · '+esc(classes.find(c=>c.id===s.class_id)?.name||'Class unavailable')+'</option>').join('');const {data,error}=await db.from('school_fee_records').select('id,student_id,academic_year,term,amount_due,amount_paid,payment_status,note,updated_at').eq('school_id',profile.school_id).eq('academic_year',year);if(error)throw error;feeRecords=data||[];renderFees()}
function renderFees(){if(profile?.role!=='admin')return;const year=$('feeFilterYear').value.trim()||currentAcademicYear(),term=$('feeFilterTerm').value||'First Term',statusFilter=$('feeFilterStatus').value,query=$('feeSearch').value.trim().toLowerCase();const all=students.filter(s=>s.active&&(s.admission_status||'admitted')==='admitted').map(s=>{const record=feeRecords.find(r=>r.student_id===s.id&&r.academic_year===year&&r.term===term);const status=record?.payment_status||'unpaid';return {student:s,record,status,due:Number(record?.amount_due)||0,paid:Number(record?.amount_paid)||0,balance:Math.max(0,(Number(record?.amount_due)||0)-(Number(record?.amount_paid)||0))}});const filtered=all.filter(x=>(!query||x.student.full_name.toLowerCase().includes(query)||(x.student.student_code||'').toLowerCase().includes(query))&&(statusFilter==='all'||x.status===statusFilter));$('feePaidCount').textContent=all.filter(x=>x.status==='paid').length;$('feePartCount').textContent=all.filter(x=>x.status==='part_payment').length;$('feeUnpaidCount').textContent=all.filter(x=>x.status==='unpaid').length;$('feeCollected').textContent=naira(all.reduce((sum,x)=>sum+x.paid,0));$('feeRecordCount').textContent=all.length+' students · '+year+' · '+term;$('feeList').innerHTML=filtered.map(x=>'<div class="item"><div style="flex:1;min-width:0"><strong>'+esc(x.student.full_name)+'</strong><br><small>'+esc(x.student.student_code||'No student ID')+' · '+esc(classes.find(c=>c.id===x.student.class_id)?.name||'Class unavailable')+'</small><br><small>Due: '+(x.record?naira(x.due):'Not set')+' · Paid: '+naira(x.paid)+' · Balance: '+(x.record?naira(x.balance):'Not set')+'</small><br><span class="status">'+(x.status==='part_payment'?'Part payment':x.status==='paid'?'Paid':'Unpaid')+'</span>'+(x.record?.note?'<br><small>Note: '+esc(x.record.note)+'</small>':'')+'</div><button type="button" class="secondary" data-fee-edit="'+esc(x.student.id)+'" data-fee-due="'+(x.record?esc(String(x.due)):'')+'" data-fee-paid="'+esc(String(x.paid))+'" data-fee-note="'+esc(x.record?.note||'')+'">Record / update</button></div>').join('')||'<p class="muted">No students match this filter.</p>'}
$('feeFilterYear').addEventListener('change',()=>loadFeeRecords().catch(e=>msg(e.message||'Unable to load fees.','error')));
['feeFilterTerm','feeFilterStatus','feeSearch'].forEach(id=>$(id).addEventListener('input',renderFees));
$('feeList').addEventListener('click',e=>{const b=e.target.closest('button[data-fee-edit]');if(!b)return;$('feeStudent').value=b.dataset.feeEdit;$('feeAcademicYear').value=$('feeFilterYear').value.trim()||currentAcademicYear();$('feeTerm').value=$('feeFilterTerm').value;$('feeAmountDue').value=b.dataset.feeDue;$('feeAmountPaid').value=b.dataset.feePaid||'0';$('feeNote').value=b.dataset.feeNote||'';$('feeForm').scrollIntoView({behavior:'smooth',block:'start'})});
$('feeForm').addEventListener('submit',async e=>{e.preventDefault();if(profile?.role!=='admin'){msg('Only the school admin can manage fee records.','error');return}const f=e.currentTarget;busy(f,true);try{const studentId=$('feeStudent').value,year=$('feeAcademicYear').value.trim(),term=$('feeTerm').value,due=Number($('feeAmountDue').value),paid=Number($('feeAmountPaid').value);if(!studentId||!year||!Number.isFinite(due)||due<=0||!Number.isFinite(paid)||paid<0||paid>due)throw new Error('Enter a valid student, academic year, fee due, and amount paid. Amount paid cannot exceed the total fee due.');const {error}=await db.from('school_fee_records').upsert({school_id:profile.school_id,student_id:studentId,academic_year:year,term,amount_due:due,amount_paid:paid,note:$('feeNote').value.trim()||null,recorded_by:user.id,updated_at:new Date().toISOString()},{onConflict:'student_id,academic_year,term'});if(error)throw error;$('feeFilterYear').value=year;$('feeFilterTerm').value=term;await loadFeeRecords();msg('School fee record saved.','success')}catch(err){msg(err.message||'Could not save fee record.','error')}finally{busy(f,false)}});
function renderIntake(){const assignedClass=classes.find(c=>c.teacher_id===user?.id);const rows=students.filter(s=>assignedClass&&s.class_id===assignedClass.id&&s.active&&(s.admission_status||'admitted')==='admitted').sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));$('intakeCount').textContent=rows.length+' students';$('intakeList').innerHTML=rows.map(s=>'<div class="item"><div style="flex:1;min-width:0"><strong>'+esc(s.full_name)+'</strong><br><small>'+esc(s.student_code||'Student ID pending')+' · '+esc(assignedClass.name)+'</small><br><small>Added '+esc(s.created_at?s.created_at.slice(0,10):'date unavailable')+'</small></div><button type="button" class="secondary" data-intake-student="'+esc(s.id)+'">View profile</button></div>').join('')||'<p class="muted">No students are currently assigned to your class.</p>'}
